<?php
declare(strict_types=1);header('Content-Type:text/html;charset=UTF-8');header('Cache-Control:no-transform,no-store,private');require dirname(__DIR__,2).'/bootstrap.php';require_once __DIR__.'/automatic-common-setup.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\AutomaticJudgeBrowserService;use App\Services\SpecialCategoryService;Auth::requireAdmin();$pdo=Database::connection();$userId=(int)(Auth::user()['id']??0);$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);$error='';$notice='';$s=$pdo->prepare("SELECT r.*,e.name event_name FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.id=:id AND r.scoring_mode='automated'");$s->execute(['id'=>$roundId]);$round=$s->fetch();if(!$round){http_response_code(404);exit('Automatic scoring round not found.');}if($_SERVER['REQUEST_METHOD']==='POST'&&Csrf::verify($_POST['_csrf']??null)&&($_POST['action']??'')==='unlock_judge'){$judgeId=(int)($_POST['judge_id']??0);$reason=trim((string)($_POST['reason']??''));try{AutomaticJudgeBrowserService::unlock($pdo,$roundId,$judgeId,$userId,$reason);$pdo->prepare("UPDATE bdc_scoring_rounds SET status=CASE WHEN status='scores_submitted' THEN 'draft' ELSE status END WHERE id=:r")->execute(['r'=>$roundId]);$notice='Judge submission reopened. Existing marks remain available for correction and resubmission.';}catch(Throwable $e){$error=$e->getMessage();}}$category=SpecialCategoryService::isSpecial((string)$round['division'])?SpecialCategoryService::label((string)$round['division']):ucwords(str_replace('_',' ',(string)$round['division']));$setup=$round['round_type']==='final'?'':bdcRenderAutomaticCommonSetup($roundId);AutomaticJudgeBrowserService::syncRound($pdo,$roundId);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Automatic Scoring | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.matrix th{white-space:nowrap;position:sticky;top:0;background:#fff}.provisional{background:#fff3cd}.score-high{font-weight:800}.status-submitted{color:#198754}.status-scoring{color:#0d6efd}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Admin</a><div><a class="btn btn-outline-light btn-sm" href="./?mode=automated">All Rounds</a> <a class="btn btn-danger btn-sm" href="../live-screen/control.php?round_id=<?=$roundId?>">Live Screen</a></div></div></nav><main class="container-fluid py-4" style="max-width:1800px"><div class="d-flex justify-content-between"><div><div class="text-primary fw-bold">AUTOMATIC SCORING</div><h1 class="h3"><?=e($round['event_name'])?></h1><div class="text-muted"><?=e($category)?> · <?=e(ucfirst($round['round_type']))?></div></div><span class="badge text-bg-warning align-self-start">LIVE / PROVISIONAL</span></div><?php if($error):?><div class="alert alert-danger mt-3"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success mt-3"><?=e($notice)?></div><?php endif;?><?=$setup?><div class="card shadow-sm mt-4"><div class="card-header d-flex justify-content-between align-items-center"><strong>Judge Progress</strong><span class="small text-muted">Auto refresh every 1.5 seconds</span></div><div class="card-body" id="judgeProgress">Loading…</div></div><div class="card shadow-sm mt-4"><div class="card-header d-flex flex-wrap justify-content-between align-items-center gap-2"><div><strong>Competitor Scoring Matrix</strong><div class="small text-muted">Current scores are provisional until the round is calculated.</div></div><div class="d-flex gap-2"><select id="sortMode" class="form-select form-select-sm"><option value="score_desc">Score High → Low</option><option value="score_asc">Score Low → High</option><option value="bib">Bib Number</option><option value="name">Name</option><option value="original">Original Order</option></select><label class="btn btn-outline-secondary btn-sm"><input id="autoSort" type="checkbox" checked> Auto Sort</label></div></div><div class="card-body p-0"><div class="table-responsive" style="max-height:70vh"><table class="table table-bordered table-hover align-middle matrix mb-0"><thead id="matrixHead"></thead><tbody id="matrixBody"><tr><td>Loading…</td></tr></tbody></table></div></div></div></main><script>const rid=<?=$roundId?>,csrf=<?=json_encode(Csrf::token())?>;let data=null,original=[];const jp=document.getElementById('judgeProgress'),head=document.getElementById('matrixHead'),body=document.getElementById('matrixBody'),sort=document.getElementById('sortMode'),auto=document.getElementById('autoSort');function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function renderJudges(){jp.innerHTML=data.judges.map(j=>`<div class="border rounded p-2 mb-2 d-flex flex-wrap justify-content-between gap-2"><div><strong>${esc(j.judge_name)}${Number(j.is_chief)?' ★':''}</strong> <span class="badge text-bg-secondary">${esc(String(j.scoring_scope).toUpperCase())}</span></div><div><strong class="status-${esc(j.session_status)}">${esc(String(j.session_status).replaceAll('_',' ').toUpperCase())}</strong> · ${j.done}/${j.total} · ${j.percent}% ${j.session_status==='submitted'?`<button class="btn btn-sm btn-outline-warning ms-2" onclick="unlockJudge(${j.judge_id},'${esc(j.judge_name)}')">Reopen</button>`:''}</div></div>`).join('')}function sortedRows(){let rows=[...data.entries];if(!auto.checked&&sort.value==='original')return original.map(i=>rows.find(x=>(x.id??x.pair_id)===i)).filter(Boolean);switch(sort.value){case'score_asc':rows.sort((a,b)=>(a.score??999999)-(b.score??999999));break;case'bib':rows.sort((a,b)=>(a.bib_number??a.pair_number)-(b.bib_number??b.pair_number));break;case'name':rows.sort((a,b)=>String(a.display_name??a.leader_name).localeCompare(String(b.display_name??b.leader_name)));break;case'original':break;default:if(data.round_type!=='final')rows.sort((a,b)=>(b.score??0)-(a.score??0));}return rows}function renderMatrix(){const js=data.judge_columns;head.innerHTML='<tr><th>Provisional</th><th>Competitor / Couple</th>'+js.map(j=>`<th>J${j.judge_order}${Number(j.is_chief)?'★':''}<br><small>${esc(j.judge_name)}</small></th>`).join('')+(data.round_type==='final'?'':'<th>Current Score</th>')+'</tr>';body.innerHTML=sortedRows().map((x,i)=>`<tr><td class="provisional">${data.round_type==='final'?'—':i+1}</td><td><strong>${data.round_type==='final'?'Couple '+x.pair_number:'#'+x.bib_number+' '+esc(x.display_name)}</strong>${data.round_type==='final'?'<br>'+esc(x.leader_name)+' & '+esc(x.follower_name):'<br><small>'+esc(x.dance_role)+'</small>'}</td>${js.map(j=>`<td>${esc(x.marks[j.id]??'—')}</td>`).join('')}${data.round_type==='final'?'':`<td class="score-high">${Number(x.score).toFixed(1)}</td>`}</tr>`).join('')}async function refresh(){try{const r=await fetch('automatic-live-data.php?round_id='+rid+'&_='+Date.now(),{cache:'no-store'}),j=await r.json();if(!j.ok)return;if(!data)original=j.entries.map(x=>x.id??x.pair_id);data=j;renderJudges();renderMatrix()}catch(e){console.error(e)}}function unlockJudge(id,name){const reason=prompt('Reason for reopening '+name+' submission:');if(!reason)return;const f=document.createElement('form');f.method='post';f.innerHTML=`<input type="hidden" name="_csrf" value="${esc(csrf)}"><input type="hidden" name="action" value="unlock_judge"><input type="hidden" name="judge_id" value="${id}"><input type="hidden" name="reason" value="${esc(reason)}">`;document.body.appendChild(f);f.submit()}sort.addEventListener('change',()=>data&&renderMatrix());auto.addEventListener('change',()=>data&&renderMatrix());refresh();setInterval(refresh,1500);</script></body></html>